"""
MicroQueryRunner — fires micro-queries to LLM via injectable research_fn.
Enforces single-fact JSON responses. LLM = search engine only.
"""

import json
import time
from dataclasses import dataclass, field
from typing import Callable, Optional

from .micro_query_generator import MicroQuery

MICRO_FACT_PROMPT = """Answer this factual question with a SINGLE data point.
Format: {{"fact": "...", "value": "...", "confidence": 0.0-1.0, "source": "...", "date": "YYYY-MM-DD"}}

Question: {question}
Expected answer type: {expected_type}

Rules:
- ONE fact only. No reasoning, no explanation, no context.
- If you don't know, return {{"fact": null, "confidence": 0.0}}
- Include source URL or publication name if available."""

BATCH_SIZE = 5
BATCH_DELAY_S = 1.0


@dataclass
class MicroQueryResult:
    query: MicroQuery
    raw_response: str
    parsed_fact: Optional[dict] = None
    parse_success: bool = False

    def to_dict(self) -> dict:
        return {
            "query": self.query.to_dict(),
            "raw_response": self.raw_response[:500],
            "parsed_fact": self.parsed_fact,
            "parse_success": self.parse_success,
        }


@dataclass
class RunnerStats:
    queries_fired: int = 0
    responses_received: int = 0
    parse_successes: int = 0
    parse_failures: int = 0

    def to_dict(self) -> dict:
        return {
            "queries_fired": self.queries_fired,
            "responses_received": self.responses_received,
            "parse_successes": self.parse_successes,
            "parse_failures": self.parse_failures,
            "parse_success_rate": round(
                self.parse_successes / max(self.responses_received, 1), 3
            ),
        }

"""
compound_paths.py — Compound path recommendations and transition failure rates.

Loads path/transition data from data/intelligence/scale_aware/paths.json.
Provides path lookup, transition failure rates, and step-by-step recommendations.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from pathlib import Path

# ---------------------------------------------------------------------------
# Seed file path
# ---------------------------------------------------------------------------

_SEED_FILE = (
    Path(__file__).resolve().parents[5]
    / "data" / "intelligence" / "scale_aware" / "paths.json"
)


# ---------------------------------------------------------------------------
# Dataclasses
# ---------------------------------------------------------------------------

@dataclass
class PathStep:
    step: int
    stage: str
    action: str
    capital_required: float
    duration_weeks: int
    success_metric: str

    def __post_init__(self) -> None:
        if self.step < 1:
            raise ValueError(f"PathStep.step must be >= 1, got {self.step}")
        if self.capital_required < 0:
            raise ValueError(f"PathStep.capital_required must be >= 0, got {self.capital_required}")
        if self.duration_weeks < 1:
            raise ValueError(f"PathStep.duration_weeks must be >= 1, got {self.duration_weeks}")

    @classmethod
    def from_dict(cls, data: dict) -> "PathStep":
        return cls(
            step=int(data["step"]),
            stage=data["stage"],
            action=data["action"],
            capital_required=float(data["capital_required"]),
            duration_weeks=int(data["duration_weeks"]),
            success_metric=data["success_metric"],
        )


@dataclass
class CompoundPath:
    path_id: str
    label: str
    description: str
    start_stage: str
    end_stage: str
    steps: list[PathStep] = field(default_factory=list)
    total_duration_weeks: int = 0
    total_capital_required: float = 0.0
    realistic_failure_rate: float = 0.0
    key_risks: list[str] = field(default_factory=list)

    def __post_init__(self) -> None:
        if not self.path_id:
            raise ValueError("CompoundPath.path_id must not be empty")
        if not 0.0 <= self.realistic_failure_rate <= 1.0:
            raise ValueError(
                f"realistic_failure_rate must be 0.0–1.0, got {self.realistic_failure_rate}"
            )

    @classmethod
    def from_dict(cls, data: dict) -> "CompoundPath":
        return cls(

                data.get("prevalence_in_bootstrapped", 0.05)
            ),
            real_examples=dict(data.get("real_examples", {})),
            commodity_data_sources=list(data.get("commodity_data_sources", [])),
            high_switching_cost_examples=list(
                data.get("high_switching_cost_examples", [])
            ),
        )

    @property
    def is_rare(self) -> bool:
        """True if this moat type occurs in <5% of bootstrapped businesses."""
        return self.prevalence_in_bootstrapped < 0.05


# ---------------------------------------------------------------------------
# Module-level cache
# ---------------------------------------------------------------------------

_MOAT_TESTS: dict[str, MoatTest] | None = None


def _load_all(seed_path: Path = _SEED_PATH) -> dict[str, MoatTest]:
    if not seed_path.exists():
        return {}
    with seed_path.open("r", encoding="utf-8") as fh:
        raw = json.load(fh)

    result: dict[str, MoatTest] = {}
    for moat_type, data in raw.get("moat_types", {}).items():
        try:
            result[moat_type] = MoatTest.from_dict(moat_type, data)
        except (KeyError, ValueError) as exc:
            print(
                f"[moat_tester] Skipping malformed moat type '{moat_type}': {exc}"
            )
    return result


def _get_moat_tests(seed_path: Path = _SEED_PATH) -> dict[str, MoatTest]:
    global _MOAT_TESTS
    if _MOAT_TESTS is None:
        _MOAT_TESTS = _load_all(seed_path)
    return _MOAT_TESTS


def reload(seed_path: Path = _SEED_PATH) -> int:
    """Force reload from disk. Returns count of loaded moat types."""
    global _MOAT_TESTS
    _MOAT_TESTS = _load_all(seed_path)
    return len(_MOAT_TESTS)


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def test_moat(moat_type: str) -> Optional[MoatTest]:
    """
    Return the stress-test suite for a claimed moat type.

    Parameters
    ----------
    moat_type : str
        One of: network_effect, data_moat, brand, switching_cost,
        regulatory, economies_of_scale. Case-insensitive.

    Returns
    -------
    MoatTest or None
        Full test suite. None if moat type not found.
    """
    key = moat_type.lower().replace(" ", "_").replace("-", "_").strip()
    tests = _get_moat_tests()

    if key in tests:
        return tests[key]

