"""Tests for TechniqueOrchestrator, base dataclasses, and FallbackRouter."""

import pytest
from pathlib import Path

from ..base import TechniqueInput, TechniqueResult, OrchestratorResult
from ..orchestrator import TechniqueOrchestrator, GO_CONSENSUS_MIN, KILL_CONSENSUS_MIN
from ..fallback_router import FallbackRouter
from ....hunger.claim_parser import ParsedClaim


def _make_input(facts=None, context=None, founder=None, ecosystem=None):
    return TechniqueInput(
        facts=facts or [],
        context=context or {"industry": "saas", "business_model": "saas"},
        founder_context=founder or {"capital_usd": 1000, "hours_per_day": 4},
        ecosystem_map=ecosystem or {"players": [], "value_chain": []},
    )


def _make_technique(verdict="GO", score=0.8, confidence=0.8, tid="T_test", metadata=None):
    def fn(input: TechniqueInput) -> TechniqueResult:
        return TechniqueResult(
            technique_id=tid,
            score=score,
            confidence=confidence,
            verdict=verdict,
            reasoning_chain=["test reasoning"],
            zone_tag="K",
            metadata=metadata or {},
        )
    return fn


class TestTechniqueResult:
    def test_valid_result(self):
        r = TechniqueResult(
            technique_id="T00",
            score=0.7,
            confidence=0.8,
            verdict="GO",
            reasoning_chain=["step 1"],
        )
        assert r.is_positive
        assert not r.is_negative
        assert not r.is_uncertain

    def test_invalid_score(self):
        with pytest.raises(ValueError):
            TechniqueResult(
                technique_id="T00", score=1.5, confidence=0.8,
                verdict="GO", reasoning_chain=[]
            )

    def test_invalid_verdict(self):
        with pytest.raises(ValueError):
            TechniqueResult(
                technique_id="T00", score=0.5, confidence=0.8,
                verdict="MAYBE", reasoning_chain=[]
            )

    def test_to_dict(self):
        r = TechniqueResult(
            technique_id="T00", score=0.75, confidence=0.9,
            verdict="KILL", reasoning_chain=["bad"]
        )
        d = r.to_dict()
        assert d["technique_id"] == "T00"
        assert d["score"] == 0.75
        assert d["verdict"] == "KILL"


class TestTechniqueInput:
    def test_facts_by_dimension(self):
        facts = [
            ParsedClaim(fact="f1", dimension="base_rates"),
            ParsedClaim(fact="f2", dimension="unit_economics"),
            ParsedClaim(fact="f3", dimension="base_rates"),
        ]
        inp = _make_input(facts=facts)
        assert len(inp.facts_by_dimension("base_rates")) == 2
        assert len(inp.facts_by_dimension("unit_economics")) == 1

    def test_facts_with_min_confidence(self):
        facts = [
            ParsedClaim(fact="f1", confidence=0.9),
            ParsedClaim(fact="f2", confidence=0.3),
            ParsedClaim(fact="f3", confidence=0.7),
        ]
        inp = _make_input(facts=facts)
        assert len(inp.facts_with_min_confidence(0.7)) == 2


class TestOrchestrator:
    def test_register_and_run_single(self):
        orch = TechniqueOrchestrator()
        orch.register("T00", _make_technique(verdict="GO", tid="T00"))
        inp = _make_input()
        result = orch.run_single("T00", inp)
        assert result.verdict == "GO"
        assert result.technique_id == "T00"

    def test_run_single_unknown_raises(self):
        orch = TechniqueOrchestrator()
        with pytest.raises(KeyError):
            orch.run_single("FAKE", _make_input())

    def test_run_all_go_consensus(self):
        orch = TechniqueOrchestrator()
        for i in range(10):
            orch.register(f"T{i:02d}", _make_technique(verdict="GO", tid=f"T{i:02d}"))
        result = orch.run_all(_make_input())
        assert result.consensus == "GO"
        assert result.techniques_agreeing_go == 10

    def test_run_all_kill_consensus(self):
        orch = TechniqueOrchestrator()
        for i in range(6):
            orch.register(f"T{i:02d}", _make_technique(verdict="KILL", tid=f"T{i:02d}", score=0.2))
        result = orch.run_all(_make_input())
        assert result.consensus == "KILL"
        assert result.techniques_agreeing_kill == 6

    def test_split_consensus(self):
        orch = TechniqueOrchestrator()
        orch.register("T00", _make_technique(verdict="GO", tid="T00"))
        orch.register("T01", _make_technique(verdict="KILL", tid="T01", score=0.2))
        orch.register("T02", _make_technique(verdict="CAUTION", tid="T02", score=0.5))
        result = orch.run_all(_make_input())
        assert result.consensus == "SPLIT"

    def test_bear_cap_forces_kill(self):
        orch = TechniqueOrchestrator()
        for i in range(10):
            orch.register(f"T{i:02d}", _make_technique(verdict="GO", tid=f"T{i:02d}"))
        # Override T03 with BEAR cap metadata
        def bear_fn(inp):
            return TechniqueResult(
                technique_id="T03_adversarial_debate",
                score=0.2, confidence=0.9, verdict="KILL",
                reasoning_chain=["BEAR overwhelms"], zone_tag="K",
                metadata={"bear_score": 10},
            )
        orch.register("T03_adversarial_debate", bear_fn)
        result = orch.run_all(_make_input())
        assert result.consensus == "KILL"

    def test_fragile_block(self):
        orch = TechniqueOrchestrator()
        for i in range(10):
            orch.register(f"T{i:02d}", _make_technique(verdict="GO", tid=f"T{i:02d}"))
        def fragile_fn(inp):
            return TechniqueResult(
                technique_id="T09_durability",
                score=0.2, confidence=0.8, verdict="CAUTION",
                reasoning_chain=["FRAGILE"], zone_tag="K",
                metadata={"classification": "FRAGILE"},
            )
        orch.register("T09_durability", fragile_fn)
        result = orch.run_all(_make_input())
        assert result.fragile_block
        assert result.consensus == "INVESTIGATE"

    def test_staircase_override(self):
        orch = TechniqueOrchestrator()
        for i in range(10):
            orch.register(f"T{i:02d}", _make_technique(verdict="GO", tid=f"T{i:02d}"))
        def t7_fn(inp):
            return TechniqueResult(
                technique_id="T07_constraint_propagation",
                score=0.2, confidence=0.8, verdict="KILL",
                reasoning_chain=["capital gap too large"], zone_tag="K",
                metadata={"kill_reason": "capital"},
            )
        def t8_fn(inp):
            return TechniqueResult(
                technique_id="T08_staircase",
                score=0.7, confidence=0.7, verdict="STAIRCASE_GO",
                reasoning_chain=["viable path found"], zone_tag="T",
            )
        orch.register("T07_constraint_propagation", t7_fn)
        orch.register("T08_staircase", t8_fn)
        result = orch.run_all(_make_input())
        assert result.staircase_override

    def test_error_handling(self):
        orch = TechniqueOrchestrator()
        def bad_fn(inp):
            raise RuntimeError("boom")
        orch.register("T_bad", bad_fn)
        result = orch.run_all(_make_input())
        assert result.results["T_bad"].verdict == "NEEDS_DATA"
        assert "ERROR" in result.results["T_bad"].reasoning_chain[0]

    def test_needs_data_aggregation(self):
        orch = TechniqueOrchestrator()
        def needs_fn(inp):
            return TechniqueResult(
                technique_id="T_needs", score=0.0, confidence=0.0,
                verdict="NEEDS_DATA", reasoning_chain=["missing data"],
                needs_data=["base_rates", "unit_economics"],
            )
        orch.register("T_needs", needs_fn)
        result = orch.run_all(_make_input())
        assert "base_rates" in result.needs_data_dimensions


class TestFallbackRouter:
    def test_generate_queries_known_dimension(self):
        router = FallbackRouter()
        queries = router.generate_queries(
            ["base_rates"], {"industry": "fintech", "business_model": "saas"}
        )
        assert len(queries) >= 3
        assert all("fintech" in q.text or "saas" in q.text for q in queries)

    def test_generate_queries_unknown_dimension(self):
        router = FallbackRouter()
        queries = router.generate_queries(
            ["unknown_dim"], {"industry": "x", "business_model": "y"}
        )
        assert len(queries) >= 2

    def test_route_no_research_fn(self):
        router = FallbackRouter(research_fn=None)
        results = router.route(["base_rates"], {"industry": "x", "business_model": "y"})
        assert results == []

    def test_route_with_research_fn(self):
        def mock_research(query):
            return {"fact": f"answer to: {query}", "confidence": 0.7, "source": "test"}
        router = FallbackRouter(research_fn=mock_research)
        results = router.route(["base_rates"], {"industry": "saas", "business_model": "saas"})
        assert len(results) >= 3
        assert all(isinstance(r, ParsedClaim) for r in results)
        assert all(r.dimension == "base_rates" for r in results)

    def test_route_empty_needs(self):
        router = FallbackRouter(research_fn=lambda q: {"fact": "x"})
        assert router.route([], {}) == []

