class TestFallbackRouter:
    def test_generate_queries_known_dimension(self):
        router = FallbackRouter()
        queries = router.generate_queries(
            ["base_rates"], {"industry": "fintech", "business_model": "saas"}
        )
        assert len(queries) >= 3
        assert all("fintech" in q.text or "saas" in q.text for q in queries)

    def test_generate_queries_unknown_dimension(self):
        router = FallbackRouter()
        queries = router.generate_queries(
            ["unknown_dim"], {"industry": "x", "business_model": "y"}
        )
        assert len(queries) >= 2

    def test_route_no_research_fn(self):
        router = FallbackRouter(research_fn=None)
        results = router.route(["base_rates"], {"industry": "x", "business_model": "y"})
        assert results == []

    def test_route_with_research_fn(self):
        def mock_research(query):
            return {"fact": f"answer to: {query}", "confidence": 0.7, "source": "test"}
        router = FallbackRouter(research_fn=mock_research)
        results = router.route(["base_rates"], {"industry": "saas", "business_model": "saas"})
        assert len(results) >= 3
        assert all(isinstance(r, ParsedClaim) for r in results)
        assert all(r.dimension == "base_rates" for r in results)

    def test_route_empty_needs(self):
        router = FallbackRouter(research_fn=lambda q: {"fact": "x"})
        assert router.route([], {}) == []
